def seed_match(seed, text):
    if not seed:
        return False
    if re.fullmatch(r'[A-Za-z0-9 _()–’—/-]+', seed):
        return bool(re.search(r'(?<![A-Za-z0-9])'+re.escape(seed)+r'(?![A-Za-z0-9])',text,re.I))
    return seed.casefold() in text.casefold()

